const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([140.878144, 27.245974]);
  const buffer = point.buffer(2000); // 2 km radius

  const date2013_start = '2013-12-01';
  const date2013_end = '2013-12-15';
  const date2014_start = '2014-03-20';
  const date2014_end = '2014-04-10';

  // 2. Data Acquisition - Using Landsat 8 (available since 2013)
  const getCloudMaskedLandsat = function(startDate, endDate) {
    const col = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(buffer)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUD_COVER', 30));

    return col.median()
      .updateMask(col.count().gt(0))
      .select(['SR_B3', 'SR_B4', 'SR_B5', 'SR_B6', 'SR_B7', 'QA_PIXEL']);
  };

  const img2013 = getCloudMaskedLandsat(date2013_start, date2013_end);
  const img2014 = getCloudMaskedLandsat(date2014_start, date2014_end);

  // Check collection sizes
  const col2013 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(buffer).filterDate(date2013_start, date2013_end);
  const col2014 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(buffer).filterDate(date2014_start, date2014_end);

  const size2013 = col2013.size().getInfo();
  const size2014 = col2014.size().getInfo();

  console.log(`2013 Images: ${size2013}, 2014 Images: ${size2014}`);

  if (size2013 === 0 || size2014 === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Island detection using NDWI and MNDWI
  const computeWaterMask = function(img) {
    // Calculate NDWI and MNDWI for better water detection
    const ndwi = img.normalizedDifference(['SR_B3', 'SR_B5']).rename('NDWI'); // Green-NIR
    const mndwi = img.normalizedDifference(['SR_B3', 'SR_B6']).rename('MNDWI'); // Green-SWIR1

    // Water is where NDWI > 0 OR MNDWI > 0.1
    const water = ndwi.gt(0).or(mndwi.gt(0.1));

    // Land is the inverse
    const land = water.not();

    // Apply morphological operations to clean up small features
    return land.focal_min(1).focal_max(1);
  };

  const waterMask2013 = computeWaterMask(img2013);
  const waterMask2014 = computeWaterMask(img2014);

  // Check valid pixels
  const count2013 = waterMask2013.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: buffer,
    scale: 30,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  const count2014 = waterMask2014.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: buffer,
    scale: 30,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  console.log(`Valid pixels 2013: ${count2013}, 2014: ${count2014}`);

  if (count2013 === 0 || count2014 === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Calculation - Count connected land components (islands)
  const countIslands = function(landMask) {
    // Use connected components to identify separate land masses
    const components = landMask.connectedComponents({
      neighborhood: ee.Kernel.square(1), // 8-connectivity
      maxSize: 1024
    });

    // Count unique labels (excluding 0 which is background/water)
    const uniqueCount = components.select('labels')
      .reduceRegion({
        reducer: ee.Reducer.countDistinct(),
        geometry: buffer,
        scale: 30,
        maxPixels: 1e9
      }).get('labels');

    return ee.Number(uniqueCount).subtract(1); // Subtract 1 for background label
  };

  const islands2013 = countIslands(waterMask2013).getInfo();
  const islands2014 = countIslands(waterMask2014).getInfo();

  console.log(`Islands in 2013: ${islands2013}, 2014: ${islands2014}`);

  // 5. Validation & Final Answer
  if (islands2013 === null || islands2014 === null || 
      islands2013 === undefined || islands2014 === undefined) {
    console.log('<answer>C3</answer>');
    return;
  }

  // Check if 2013 had 2 islands and 2014 has 1 island
  if (islands2013 === 2 && islands2014 === 1) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
